CREATE DEFINER=`root`@`localhost` FUNCTION `fn_casos_cerrados_persona`(p_usuario_id VARCHAR(10)) RETURNS int
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_cerrados INT;
    SELECT COUNT(*)
    INTO v_cerrados
    FROM tbl_caso c
     WHERE c.Fk_Usuario = p_usuario_id
      AND c.Fk_Estado = 'C';
    RETURN v_cerrados;
END ;;
