CREATE DEFINER=`root`@`localhost` FUNCTION `fn_total_usuarios_inactivos`() RETURNS int
    READS SQL DATA
    DETERMINISTIC
BEGIN
	DECLARE v_usuarios INT;
    SELECT COUNT(*)
    INTO v_usuarios
    FROM tbl_usuario u
     WHERE u.Fk_Estado = '00';
    RETURN v_usuarios;
END ;;
