CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerarCargaMasiva`()
BEGIN
    DECLARE i INT DEFAULT 0;
    DECLARE v_id_persona BIGINT;
    DECLARE v_id_usuario INT DEFAULT 49;
    DECLARE v_nombre_1 VARCHAR(100);
    DECLARE v_nombre_2 VARCHAR(100);
    DECLARE v_apellido_1 VARCHAR(100);
    DECLARE v_apellido_2 VARCHAR(100);
    DECLARE v_username VARCHAR(50);
    DECLARE v_fecha_caso DATE;
    DECLARE v_municipio CHAR(3);
    DECLARE v_desastre VARCHAR(10);
    DECLARE v_descripcion TEXT;
    
    -- Desactivar restricciones temporalmente para agilizar la carga
    SET FOREIGN_KEY_CHECKS = 0;

    WHILE i < 3000 DO
        -- 1. Generación de Identidad (6 a 10 dígitos)
        SET v_id_persona = FLOOR(100000 + (RAND() * 9999900000));
        
        -- 2. Selección de Nombres y Apellidos
        SET v_nombre_1 = ELT(FLOOR(1 + (RAND() * 10)), 'Juan', 'Maria', 'Carlos', 'Ana', 'Luis', 'Diana', 'Diego', 'Paula', 'Andres', 'Camila');
        SET v_nombre_2 = ELT(FLOOR(1 + (RAND() * 10)), 'Antonio', 'Sofia', 'Javier', 'Lucia', 'Fernando', 'Elena', 'Mauricio', 'Natalia', 'Ricardo', 'Beatriz');
        SET v_apellido_1 = ELT(FLOOR(1 + (RAND() * 10)), 'Rodriguez', 'Gomez', 'Martinez', 'Lopez', 'Perez', 'Sanchez', 'Ramirez', 'Torres', 'Beltran', 'Rojas');
        SET v_apellido_2 = ELT(FLOOR(1 + (RAND() * 10)), 'Castro', 'Peña', 'Guzman', 'Ortega', 'Vargas', 'Herrera', 'Medina', 'Mora', 'Rios', 'Franco');
        
        -- 3. Definición de Usuario
        SET v_username = CONCAT(LOWER(v_nombre_1), '.', LOWER(v_apellido_1), v_id_usuario);
        
        -- 4. Lógica de Negocio para el Caso
        SET v_fecha_caso = DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 365) DAY);
        SET v_municipio = ELT(FLOOR(1 + (RAND() * 7)), 'COT', 'ANA', 'CAJ', 'ZIP', 'FAC', 'MOS', 'FUN');
        SET v_desastre = ELT(FLOOR(1 + (RAND() * 3)), 'In', 'Inund', 'SI-T');
        
        SET v_descripcion = CONCAT(
            ELT(FLOOR(1 + (RAND() * 3)), 
                'El incendio se originó por una descarga eléctrica en la zona alta de la cordillera, ', 
                'Se presentó un desbordamiento súbito del río principal debido a precipitaciones intensas, ', 
                'Un movimiento en masa en la ladera oriental impactó las estructuras por saturación de suelos, '),
            'propagándose rápidamente debido a condiciones climáticas adversas. ',
            'Mi vivienda ha sido clasificada con Pérdida Total tras la inspección técnica preliminar. ',
            'El núcleo familiar se encuentra actualmente en situación de desplazamiento en refugios temporales.'
        );

        -- INSERCIÓN EN TBL_PERSONA
        INSERT INTO tbl_persona (Id_Persona, Nombre, Apellido, Correo, Direccion, Telefono)
        VALUES (
            v_id_persona, 
            CONCAT(v_nombre_1, ' ', v_nombre_2), 
            CONCAT(v_apellido_1, ' ', v_apellido_2), 
            CONCAT(v_username, '@uadecundinamarca.edu.co'), 
            CONCAT('Carrera ', FLOOR(1 + RAND() * 20), ' #', FLOOR(1 + RAND() * 100), '-', FLOOR(1 + RAND() * 50)),
            CONCAT('3', FLOOR(100000000 + (RAND() * 899999999)))
        );

        -- INSERCIÓN EN TBL_USUARIO
        -- El hash corresponde a 'Password123' con pepper 'Proyecto1!'
        INSERT INTO tbl_usuario (Id_usuario, Nombre, Contrasena, Rol, fk_persona, fk_estado)
        VALUES (
            v_id_usuario, 
            v_username, 
            '$2b$12$K1R7x/W8zB.p2Qp9oZ3M1.7Xy.L5GqR7uS9vA2bC3dE4fG5hI6jK.', -- Hash simulado consistente
            'User', 
            v_id_persona, 
            '01'
        );

        -- INSERCIÓN EN TBL_CASO
        INSERT INTO tbl_caso (Fecha, Descripcion, Direccion, Personas_Afectadas, Fk_Usuario, Fk_Desastre, Fk_Estado, Fk_Ciu)
        VALUES (
            v_fecha_caso, 
            v_descripcion, 
            CONCAT('Sector ', ELT(FLOOR(1 + (RAND() * 4)), 'Rural', 'Urbano', 'Norte', 'Sur')), 
            FLOOR(1 + RAND() * 10), 
            v_id_usuario, 
            v_desastre, 
            'P', 
            v_municipio
        );

        -- INSERCIÓN EN HISTORICAL
        INSERT INTO historical (username, Fk_usuario, Accion, Descripcion, created_at)
        VALUES (
            v_username, 
            v_id_usuario, 
            ELT(FLOOR(1 + (RAND() * 5)), 'Crear', 'ingresar', 'actualizar/modificar', 'enviar', 'generar'), 
            'Registro de evento crítico generado por el sistema de emergencias', 
            DATE_ADD(v_fecha_caso, INTERVAL 2 HOUR)
        );

        SET v_id_usuario = v_id_usuario + 1;
        SET i = i + 1;
    END WHILE;

    SET FOREIGN_KEY_CHECKS = 1;
END ;;
DELIMITER ;
