CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerarDatosMasivos`()
BEGIN
    DECLARE i INT DEFAULT 0;
    DECLARE v_id_persona BIGINT;
    DECLARE v_id_usuario INT DEFAULT 49;
    DECLARE v_nombre VARCHAR(100);
    DECLARE v_apellido VARCHAR(100);
    DECLARE v_username VARCHAR(50);
    DECLARE v_fecha_caso DATE;
    DECLARE v_municipio CHAR(3);
    DECLARE v_desastre VARCHAR(10);
    DECLARE v_descripcion TEXT;
    
    -- Desactivar llaves para velocidad de inserción
    SET FOREIGN_KEY_CHECKS = 0;

    WHILE i < 3000 DO
        -- 1. Generar datos aleatorios básicos
        SET v_id_persona = FLOOR(1000000 + (RAND() * 9990000000)); -- ID entre 7 y 10 dígitos
        SET v_nombre = ELT(FLOOR(1 + (RAND() * 10)), 'Juan', 'Maria', 'Carlos', 'Ana', 'Luis', 'Diana', 'Diego', 'Paula', 'Andres', 'Camila');
        SET v_apellido = ELT(FLOOR(1 + (RAND() * 10)), 'Rodriguez', 'Gomez', 'Martinez', 'Lopez', 'Perez', 'Sanchez', 'Ramirez', 'Torres', 'Beltran', 'Rojas');
        SET v_username = CONCAT(LOWER(v_nombre), v_id_usuario);
        SET v_fecha_caso = DATE_ADD('2024-01-01', INTERVAL FLOOR(RAND() * 400) DAY);
        SET v_municipio = ELT(FLOOR(1 + (RAND() * 5)), 'COT', 'ANA', 'CAJ', 'ZIP', 'FAC');
        SET v_desastre = ELT(FLOOR(1 + (RAND() * 3)), 'In', 'Inund', 'SI-T');
        
        -- 2. Generar descripción realista basada en tu ejemplo
        SET v_descripcion = CONCAT(
            ELT(FLOOR(1 + (RAND() * 3)), 
                'El incendio se originó por una falla eléctrica en la zona alta, ', 
                'El desbordamiento súbito se produjo por lluvias torrenciales, ', 
                'El movimiento en masa fue provocado por la saturación del suelo, '),
            ELT(FLOOR(1 + (RAND() * 3)),
                'afectando gravemente las estructuras habitacionales y el núcleo familiar. ',
                'superando las brechas de seguridad y generando daños estructurales. ',
                'impactando directamente sobre la vivienda y zonas comunes. '),
            'La propiedad ha sido clasificada con pérdida total tras la inspección técnica preliminar.'
        );

        -- 3. Inserción en tbl_persona
        INSERT INTO tbl_persona (Id_Persona, Nombre, Apellido, Correo, Direccion, Telefono)
        VALUES (v_id_persona, v_nombre, v_apellido, CONCAT(v_username, '@simulacion.com'), 
                CONCAT('Calle ', FLOOR(1 + RAND() * 100), ' #', FLOOR(1 + RAND() * 50)), '3101234567');

        -- 4. Inserción en tbl_usuario
        -- Nota: El hash es un ejemplo realista de bcrypt (Password123 + Proyecto1!)
        INSERT INTO tbl_usuario (Id_usuario, Nombre, Contrasena, Rol, fk_persona, fk_estado)
        VALUES (v_id_usuario, v_username, '$2b$12$R9h/cIPz7gi.URXYpSxv2u5Z6lXp0rK5k6v.GZq/E3.2uM1234567', 'User', v_id_persona, '01');

        -- 5. Inserción en tbl_caso
        INSERT INTO tbl_caso (Fecha, Descripcion, Direccion, Personas_Afectadas, Fk_Usuario, Fk_Desastre, Fk_Estado, Fk_Ciu)
        VALUES (v_fecha_caso, v_descripcion, 'Vereda El Sector Central', FLOOR(1 + RAND() * 6), v_id_usuario, v_desastre, 'P', v_municipio);

        -- 6. Inserción en historical
        INSERT INTO historical (username, Fk_usuario, Accion, Descripcion, created_at)
        VALUES (v_username, v_id_usuario, 
                ELT(FLOOR(1 + (RAND() * 5)), 'Crear', 'ingresar', 'actualizar/modificar', 'enviar', 'generar'),
                'Registro automático de simulacro de emergencia', 
                NOW());

        SET v_id_usuario = v_id_usuario + 1;
        SET i = i + 1;
    END WHILE;

    SET FOREIGN_KEY_CHECKS = 1;
END ;;
DELIMITER ;
