CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerarRegistrosFinales`()
BEGIN
    DECLARE i INT DEFAULT 0;
    DECLARE v_id_usuario INT;
    DECLARE v_id_persona BIGINT;
    DECLARE v_p_nom, v_s_nom, v_p_ape, v_s_ape VARCHAR(50);
    DECLARE v_username VARCHAR(20);
    DECLARE v_password_hash VARCHAR(255);
    DECLARE v_fecha_nac DATE;
    DECLARE v_fecha_caso DATE;
    DECLARE v_id_caso INT;
    DECLARE v_desastre VARCHAR(10);
    DECLARE v_municipio VARCHAR(10);
    DECLARE v_vereda VARCHAR(50);
    DECLARE v_estado_caso CHAR(1);
    DECLARE v_accion VARCHAR(50);
    DECLARE v_desc_hist TEXT;
    DECLARE v_desc_caso TEXT;

    -- Hash pre-calculado: Password123 + Proyecto1!
    SET v_password_hash = '$2b$12$K1R7x/W8zB.p2Qp9oZ3M1.7Xy.L5GqR7uS9vA2bC3dE4fG5hI6jK.';
    
    SET FOREIGN_KEY_CHECKS = 0;

    WHILE i < 100 DO
        -- 1. Selección de Nombres y Apellidos para Persona y Username
		SET v_p_nom = ELT(FLOOR(1 + (RAND() * 30)), 
			'Maira', 'Mayra', 'Myra', 'Keila', 'Keyla', 
			'Eider', 'Yared', 'Nadir', 'Zaid', 'Ian', 
			'Ilse', 'Frida', 'Guido', 'Hassan', 'Ivette', 
			'Joss', 'Kendra', 'Lester', 'Misael', 'Naila', 
			'Oswin', 'Pavel', 'Quinn', 'Rene', 'Sasha', 
			'Tania', 'Uriel', 'Vania', 'Willa', 'Xander'
		);

		-- 2. Segundo Nombre: Variedad unisex y nombres de distinta sonoridad
		SET v_s_nom = ELT(FLOOR(1 + (RAND() * 30)), 
			'Alexis', 'Belen', 'Cruz', 'Denis', 'Elias', 
			'Fabi', 'Gael', 'Hany', 'Ines', 'Jade', 
			'Kael', 'Lian', 'Mica', 'Noel', 'Odeth', 
			'Paz', 'Rayan', 'Sol', 'Teo', 'Uri', 
			'Vico', 'Yael', 'Zion', 'Alon', 'Blaise', 
			'Cian', 'Dante', 'Emy', 'Frey', 'Gabi'
		);

		-- 3. Primer Apellido: Apellidos menos frecuentes (Set A)
		SET v_p_ape = ELT(FLOOR(1 + (RAND() * 30)), 
			'Andrade', 'Barreto', 'Cisneros', 'Duarte', 'Escamilla', 
			'Ferreira', 'Galindo', 'Hurtado', 'Iñiguez', 'Joya', 
			'Lara', 'Magana', 'Negrete', 'Olmos', 'Peralta', 
			'Quezada', 'Rosado', 'Salgado', 'Tirado', 'Urbano', 
			'Valdes', 'Wong', 'Ximenez', 'Yañez', 'Zepeda', 
			'Alcaraz', 'Briones', 'Campos', 'Dorado', 'Elias'
		);

		-- 4. Segundo Apellido: Apellidos menos frecuentes (Set B)
		SET v_s_ape = ELT(FLOOR(1 + (RAND() * 30)), 
			'Aranda', 'Berrío', 'Coronado', 'Del Valle', 'Estrada', 
			'Fajardo', 'Garrido', 'Haro', 'Izquierdo', 'Juarez', 
			'Linares', 'Maldonado', 'Noriega', 'Orellana', 'Pacheco', 
			'Quintana', 'Robles', 'Salinas', 'Toscano', 'Ugalde', 
			'Valenzuela', 'Villar', 'Zayas', 'Amescua', 'Becerra', 
			'Carranza', 'De la Rosa', 'Espino', 'Flores', 'Gaona'
		);        
        -- Username: Mezcla de Inicial Nombre + Apellido + sufijo aleatorio (Max 20 chars)
        SET v_username = LOWER(
			CONCAT(
				LEFT(v_p_nom, 1),                 -- Inicial del primer nombre
				LEFT(v_s_nom, 1),                 -- Inicial del segundo nombre
				LEFT(v_p_ape, 5),                 -- Primeras 5 letras del primer apellido
				LEFT(v_s_ape, 3),                 -- Primeras 3 letras del segundo apellido
				SUBSTRING('@$!%*?&.,;:\-_', FLOOR(1 + (RAND() * 14)), 1), -- Carácter especial al azar
				FLOOR(100 + (RAND() * 899))       -- Número aleatorio entre 100 y 999
			)
		);
        
        SET v_username = LEFT(v_username, 20);
        -- 2. INSERT TBL_USUARIO
        INSERT INTO tbl_usuario (Nombre, Contrasena, Rol, fk_estado)
        VALUES (v_username, v_password_hash, 'User', '01');
        SET v_id_usuario = LAST_INSERT_ID();

        -- 3. INSERT TBL_PERSONA
        SET v_id_persona = FLOOR(1000000 + (RAND() * 9000000000)); -- 7 a 10 dígitos
        SET v_fecha_nac = DATE_SUB('2005-01-01', INTERVAL FLOOR(RAND() * 15000) DAY);
        
        INSERT INTO tbl_persona (
            Id_Persona, Pri_Nom, Seg_Nom, Pri_Ape, Seg_Ape,
            fk_Tipo_documento, Fecha_nacimiento, fk_Usuario,
            Edad, Direccion, Num_Contact, Email
        ) VALUES (
            v_id_persona, v_p_nom, v_s_nom, v_p_ape, v_s_ape,
            'CC', v_fecha_nac, v_id_usuario,
            TIMESTAMPDIFF(YEAR, v_fecha_nac, CURDATE()),
            CONCAT('Cl ', FLOOR(1+RAND()*99), ' No ', FLOOR(1+RAND()*50), '-', FLOOR(1+RAND()*20)),
            CONCAT('3', FLOOR(100000000 + (RAND() * 899999999))),
            CONCAT(v_username, '@gmail.com')
        );

        -- 4. Definición de Municipio (Escogiendo entre 10 de tu lista)
        SET v_municipio = ELT(FLOOR(1 + (RAND() * 16)), 
            'AGD', 'ANA', 'CAJ', 'FAC', 'GIR', 'LAC', 'LAM', 'ZIP', 'CHI', 'FUN', 'MAC', 'MAD', 'YAC', 'ZIPC', 'VIO', 'VIL');
        
        -- 5. Definición de Vereda (4 opciones al azar)
        SET v_vereda = ELT(FLOOR(1 + (RAND() * 7)), 
            'Vereda Cajon', 'Vereda San Ignacio', 'Vereda El rosal', 'Vereda Resguardo Manzanos Arriba', 'Vereda Resguardo Arriba', 'Vereda Quigua', 'Vereda Mochileros');

        -- 6. Lógica de Caso (Descripciones según Desastre)
        SET v_desastre = ELT(FLOOR(1 + (RAND() * 4)), 'In', 'Inund', 'SI-T', 'In');
        SET v_desc_caso = CASE v_desastre
            WHEN 'In' THEN 'Un incendio originado por una descarga eléctrica cerca a la zona rural se propagó desde el valle hasta la zona urbana afectando a las casas situadas a la entrada del prueblo. Mi vivienda ha sido clasificada con Pérdida Total al ser una de las primeras a las que el fuego llegó.'
            WHEN 'Inund' THEN 'El río cercano a la vereda se desbordó debido a las fuertes lluvias y causó multiples daños para las viviendas cercanas. Entre esas se encontraba mi finca, quedando inundada en un 60% y haciendo daño a cultivos que se tenían por la zona'
            WHEN 'SI-T' THEN 'Hubo un sismo bastate fuerte en la zona rural y urbana aledaña a la vereda/municipio, causando daños en infraestructura de mi casa la cuál se encontraba a las afueras de la vereda, el epicentro del sismo según dijeron'
            ELSE 'Emergencia por remoción en masa que impactó directamente sobre las estructuras habitacionales, dejando el núcleo familiar en situación de desplazamiento por perdida total de sus viviendas. Mi casa fue catalogada como perdida parcial al estar algo alejada del deslizamiento inicial, dejando en pie cerca del 60% de la vivienda. Sin embargo se tienen daños y lesiones bastantes graves que afectan el estilo de vida allí.'
        END;

        SET v_fecha_caso = DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND()*30) DAY);
        SET v_estado_caso = ELT(FLOOR(1 + (RAND() * 4)), 'P', 'R', 'E', 'C');

        INSERT INTO tbl_caso (
            Fecha, Descripcion, Direccion, Personas_Afectadas,
            Fk_Usuario, Fk_Desastre, Fk_Ciu, Fk_Estado
        ) VALUES (
            v_fecha_caso, v_desc_caso, CONCAT(v_vereda, ' - Sector ', i+1),
            FLOOR(1 + RAND() * 7), v_id_usuario, v_desastre, v_municipio, v_estado_caso
        );
        SET v_id_caso = LAST_INSERT_ID();

        -- 7. INSERT HISTORICAL (Descripciones dinámicas según Acción)
        SET v_accion = ELT(FLOOR(1 + (RAND() * 5)), 'CREAR', 'INGRESAR', 'ACTUALIZAR/MODIFICAR', 'ENVIAR', 'GENERAR');
        
        SET v_desc_hist = CASE 
            WHEN v_accion = 'CREAR' THEN ELT(FLOOR(1+RAND()*2), 'Nuevo registro de un caso', 'Creación de un nuevo usuario')
            WHEN v_accion = 'INGRESAR' THEN 'Nuevo ingreso de usuario al aplicativo'
            WHEN v_accion = 'ACTUALIZAR/MODIFICAR' THEN 
                CONCAT('Se cambió estado del caso ', v_id_caso, ' a ', 
                       CASE v_estado_caso WHEN 'P' THEN 'Pendiente' WHEN 'R' THEN 'Registrado' WHEN 'E' THEN 'Enviado' ELSE 'Cerrado' END)
            WHEN v_accion = 'ENVIAR' THEN CONCAT('Registro de caso ', v_id_caso, ' enviado a entidad')
            ELSE 'Nuevo reporte generado por administrador del sistema'
        END;

        INSERT INTO historical (username, Fk_usuario, Accion, Descripcion, Created_at)
        VALUES (v_username, v_id_usuario, v_accion, v_desc_hist, NOW());

        SET i = i + 1;
    END WHILE;

    SET FOREIGN_KEY_CHECKS = 1;
END ;;
DELIMITER ;
