CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_user_admin`(
    IN p_user_id INT UNSIGNED,
    IN p_username VARCHAR(20),
    IN p_rol VARCHAR(20)
)
    MODIFIES SQL DATA
BEGIN
    UPDATE tbl_usuario
    SET
        Nombre = COALESCE(p_username, Nombre),
        Rol = COALESCE(p_rol, Rol)
    WHERE Id_usuario = p_user_id;
END ;;
DELIMITER ;
